[{"seq": 37, "text": "What would it cost to move from the starter plan to enterprise?"}, {"seq": 38, "text": "Our contract is up for renewal and we want to talk about expanding usage."}, {"seq": 39, "text": "Our contract is up for renewal and we want to talk about expanding usage."}, {"seq": 40, "text": "Exporting my invoice history to CSV produces a corrupted file."}, {"seq": 41, "text": "The upgrade never activated but the payment went through; I'd like that payment returned."}, {"seq": 42, "text": "Exporting my invoice history to CSV produces a corrupted file."}, {"seq": 43, "text": "You billed me $999 for a plan I downgraded out of. Can you credit it back to my card?"}, {"seq": 44, "text": "Order shows delivered but nothing ever arrived; I want my $120 back."}, {"seq": 45, "text": "Is there a nonprofit rate? We'd roll it out to 500 volunteers."}, {"seq": 46, "text": "Where can I download my invoice history for our accountant?"}, {"seq": 47, "text": "Where can I download my invoice history for our accountant?"}, {"seq": 48, "text": "You billed me $999 for a plan I downgraded out of. Can you credit it back to my card?"}]

